-- Applied on 2026-11-02 after public GitHub Pages verification.
begin; update public.aisha_projects set site_url = case slug when 'lifelab' then 'https://aishaaismaiil.github.io/Portfolio-Aisha/life-lab/' when 'sensora' then 'https://aishaaismaiil.github.io/Portfolio-Aisha/sensora.html' when 'conduzpt' then 'https://aishaaismaiil.github.io/Portfolio-Aisha/conduzpt.html' else site_url end where slug in ('lifelab','sensora','conduzpt'); insert into public.aisha_project_releases(project_slug,version,notes,download_url,published_at) values ('lifelab','2026-11-02-guided','LifeLab geral publicado no portefólio. Vida guiada independente. IA livre e sincronização do perfil ainda não ligadas na interface.','https://aishaaismaiil.github.io/Portfolio-Aisha/life-lab/',now()),('sensora','2026-11-02-research','Apresentação de investigação e cocriação para participação social de pessoas surdocegas. Sem eficácia ou originalidade comprovadas.','https://aishaaismaiil.github.io/Portfolio-Aisha/sensora.html',now()),('conduzpt','godot-chelas-prototipo-02','Protótipo Godot 4 de Chelas com dados OpenStreetMap. Requer Godot, não é jogo de navegador nem percurso oficial de exame.','https://aishaaismaiil.github.io/Portfolio-Aisha/downloads/conduzpt-prototipo-02.zip',now()) on conflict(project_slug,version) do update set notes=excluded.notes,download_url=excluded.download_url; commit; select jsonb_build_object('projects',(select jsonb_agg(jsonb_build_object('slug',slug,'url',site_url)) from public.aisha_projects),'public_releases',(select count(*) from public.aisha_project_releases where published_at<=now()),'stellamus_documents',(select count(*) from public.docs)) as verification;
